import React from 'react';

const QuestionCard = ({ index, qa, questions, hideAnswers, onChange }) => {
  const mismatch = qa.confirmAnswer && qa.answer !== qa.confirmAnswer;

  return (
    <div className="question-block">
      <label className="question-label">Question {index + 1}</label>
      
      <select
        className="form-select"
        value={qa.question}
        onChange={e => onChange(index, 'question', e.target.value)}
      >
        <option value="">-- Select --</option>
        {questions.map((q) => (
          <option key={q.q_id} value={q.question}>
            {q.question}
          </option>
        ))}
      </select>

      <div className="input-row">
        <input
          className="form-input"
          type={hideAnswers ? "password" : "text"}
          placeholder="Answer"
          value={qa.answer}
          onChange={e => onChange(index, 'answer', e.target.value)}
        />
        <input
          className={`form-input ${mismatch ? 'input-error' : ''}`}
          type={hideAnswers ? "password" : "text"}
          placeholder="Confirm"
          value={qa.confirmAnswer}
          onChange={e => onChange(index, 'confirmAnswer', e.target.value)}
        />
      </div>
      {mismatch && <span className="error-text">Mismatch</span>}
    </div>
  );
};

export default QuestionCard;
